ValidationRule.errorConditionFormula:
AND(NOT($User.ByPassVR__c), ByPassVR__c = false && NOT(ISCHANGED(ByPassVR__c)), ISBLANK(TEXT(concorrente__c)), IsClosed = true, IsWon = false, NOT(ISCHANGED(OwnerId)), Year(DateValue(CreatedDate)) = Year(Today())
,OR(ISCHANGED(StageName),ISCHANGED(concorrente__c),ISCHANGED(LossReason__c))
)
